IDENTITY_FACTS_SQL_TEXT: Final = "WITH expected_relations(schema_name, relation_name, relation_kind) AS (\n    VALUES\n        ('ai', 'ai_attempt', 'r'),\n        ('ai', 'ai_job', 'r'),\n        ('ai', 'evaluation_case', 'r'),\n        ('ai', 'evaluation_case_result', 'r'),\n        ('ai', 'evaluation_dataset_version', 'r'),\n        ('ai', 'evaluation_result', 'r'),\n        ('ai', 'evaluation_run', 'r'),\n        ('ai', 'evaluation_suite', 'r'),\n        ('ai', 'human_evaluation', 'r'),\n        ('ai', 'judge_calibration', 'r'),\n        ('ai', 'model_definition', 'r'),\n        ('ai', 'model_route_version', 'r'),\n        ('ai', 'output_schema_version', 'r'),\n        ('ai', 'prompt_version', 'r'),\n        ('ai', 'release_approval', 'r'),\n        ('ai', 'release_decision', 'r'),\n        ('ai', 'task_definition', 'r'),\n        ('ai', 'usage_cost', 'r'),\n        ('catalog', 'affiliate_link_observation', 'r'),\n        ('catalog', 'attribute_definition', 'r'),\n        ('catalog', 'availability_observation', 'r'),\n        ('catalog', 'canonical_product', 'r'),\n        ('catalog', 'category_genre_mapping', 'r'),\n        ('catalog', 'grouping_decision', 'r'),\n        ('catalog', 'ingestion_request', 'r'),\n        ('catalog', 'offer', 'r'),\n        ('catalog', 'offer_current_projection', 'r'),\n        ('catalog', 'price_observation', 'r'),\n        ('catalog', 'product_attribute_value', 'r'),\n        ('catalog', 'product_candidate', 'r'),\n        ('catalog', 'product_group_membership', 'r'),\n        ('catalog', 'product_relation', 'r'),\n        ('catalog', 'provider_endpoint', 'r'),\n        ('catalog', 'rakuten_genre', 'r'),\n        ('catalog', 'review_aggregate_observation', 'r'),\n        ('catalog', 'shop', 'r'),\n        ('catalog', 'v_safe_offer_current', 'v'),\n        ('editorial', 'article', 'r'),\n        ('editorial', 'article_block', 'r'),\n        ('editorial', 'article_block_product', 'r'),\n        ('editorial', 'article_disclosure_context', 'r'),\n        ('editorial', 'article_link', 'r'),\n        ('editorial', 'article_methodology_binding', 'r'),\n        ('editorial', 'article_plan', 'r'),\n        ('editorial', 'article_slug', 'r'),\n        ('editorial', 'article_template_version', 'r'),\n        ('editorial', 'article_type_version', 'r'),\n        ('editorial', 'article_version', 'r'),\n        ('editorial', 'comparison_axis', 'r'),\n        ('editorial', 'comparison_value', 'r'),\n        ('editorial', 'content_schema_version', 'r'),\n        ('editorial', 'editorial_methodology_version', 'r'),\n        ('editorial', 'media_asset', 'r'),\n        ('editorial', 'recommendation', 'r'),\n        ('editorial', 'recommendation_rationale', 'r'),\n        ('editorial', 'recommendation_set', 'r'),\n        ('editorial', 'review_comment', 'r'),\n        ('editorial', 'seo_metadata_version', 'r'),\n        ('editorial', 'structured_data_manifest', 'r'),\n        ('evidence', 'claim', 'r'),\n        ('evidence', 'claim_evidence_link', 'r'),\n        ('evidence', 'fact', 'r'),\n        ('evidence', 'fact_derivation', 'r'),\n        ('evidence', 'first_hand_experience_asset', 'r'),\n        ('evidence', 'first_hand_experience_record', 'r'),\n        ('evidence', 'source', 'r'),\n        ('evidence', 'source_packet', 'r'),\n        ('evidence', 'source_packet_fact', 'r'),\n        ('evidence', 'source_packet_product', 'r'),\n        ('evidence', 'source_packet_version', 'r'),\n        ('evidence', 'source_snapshot', 'r'),\n        ('iam', 'break_glass_record', 'r'),\n        ('iam', 'permission', 'r'),\n        ('iam', 'principal', 'r'),\n        ('iam', 'principal_role_assignment', 'r'),\n        ('iam', 'role', 'r'),\n        ('iam', 'role_permission', 'r'),\n        ('iam', 'service_principal', 'r'),\n        ('iam', 'session_revocation', 'r'),\n        ('iam', 'user_account', 'r'),\n        ('ops', 'audit_event', 'r'),\n        ('ops', 'idempotency_record', 'r'),\n        ('ops', 'inbox_receipt', 'r'),\n        ('ops', 'job', 'r'),\n        ('ops', 'job_attempt', 'r'),\n        ('ops', 'object_artifact', 'r'),\n        ('ops', 'outbox_event', 'r'),\n        ('ops', 'runtime_setting_version', 'r'),\n        ('policy', 'bundle_rule', 'r'),\n        ('policy', 'finding', 'r'),\n        ('policy', 'gate_decision', 'r'),\n        ('policy', 'policy_bundle', 'r'),\n        ('policy', 'quality_check_run', 'r'),\n        ('policy', 'quality_score', 'r'),\n        ('policy', 'rule_version', 'r'),\n        ('policy', 'waiver', 'r'),\n        ('portfolio', 'action_candidate', 'r'),\n        ('portfolio', 'category', 'r'),\n        ('portfolio', 'intent_cluster', 'r'),\n        ('portfolio', 'intent_cluster_keyword', 'r'),\n        ('portfolio', 'keyword', 'r'),\n        ('portfolio', 'keyword_metric_observation', 'r'),\n        ('portfolio', 'opportunity_assessment', 'r'),\n        ('portfolio', 'site', 'r')\n),\nlogin_identity AS (\n    SELECT role_record.oid AS login_oid,\n           SESSION_USER::text AS login_role,\n           role_record.rolsuper AS is_superuser,\n           role_record.rolbypassrls AS bypass_rls,\n           role_record.rolcreaterole AS create_role,\n           role_record.rolcreatedb AS create_database\n      FROM pg_catalog.pg_roles AS role_record\n     WHERE role_record.rolname = SESSION_USER\n       AND SESSION_USER = CURRENT_USER\n),\neffective_groups AS (\n    SELECT COALESCE(\n               pg_catalog.array_agg(candidate.rolname::text\n                                    ORDER BY candidate.rolname)\n                   FILTER (WHERE candidate.oid IS NOT NULL),\n               ARRAY[]::text[]\n           ) AS inherited_groups\n      FROM login_identity AS login\n      LEFT JOIN pg_catalog.pg_roles AS candidate\n        ON candidate.oid <> login.login_oid\n       AND pg_catalog.pg_has_role(login.login_oid, candidate.oid, 'MEMBER')\n),\nrequired_group_gate AS (\n    SELECT pg_catalog.pg_has_role(\n               login.login_oid, required_role.oid, 'USAGE'\n           ) AS usable\n      FROM login_identity AS login\n      JOIN pg_catalog.pg_roles AS required_role\n        ON required_role.rolname = :required_group\n),\nselected_relations AS (\n    SELECT expected.schema_name,\n           expected.relation_name,\n           expected.relation_kind,\n           relation_record.oid,\n           relation_record.relowner\n      FROM expected_relations AS expected\n      JOIN pg_catalog.pg_namespace AS namespace_record\n        ON namespace_record.nspname = expected.schema_name\n      JOIN pg_catalog.pg_class AS relation_record\n        ON relation_record.relnamespace = namespace_record.oid\n       AND relation_record.relname = expected.relation_name\n       AND relation_record.relkind = expected.relation_kind\n),\nselected_inventory_gate AS (\n    SELECT pg_catalog.count(*) = 104\n       AND pg_catalog.count(DISTINCT oid) = 104 AS exact\n      FROM selected_relations\n),\nselected_relation_ownership AS (\n    SELECT COALESCE(\n               pg_catalog.bool_or(\n                   selected.relowner = login.login_oid\n                   OR pg_catalog.pg_has_role(\n                       login.login_oid, selected.relowner, 'MEMBER'\n                   )\n               ),\n               false\n           ) AS owns_selected_relation\n      FROM login_identity AS login\n      CROSS JOIN selected_relations AS selected\n),\ndangerous_owner_gate AS (\n    SELECT NOT EXISTS (\n               SELECT 1\n                 FROM pg_catalog.pg_database AS database_record\n                 CROSS JOIN login_identity AS login\n                WHERE database_record.datname = pg_catalog.current_database()\n                  AND (\n                      database_record.datdba = login.login_oid\n                      OR pg_catalog.pg_has_role(\n                          login.login_oid, database_record.datdba, 'MEMBER'\n                      )\n                  )\n           )\n       AND NOT EXISTS (\n               SELECT 1\n                 FROM pg_catalog.pg_namespace AS namespace_record\n                 CROSS JOIN login_identity AS login\n                WHERE namespace_record.nspname = ANY(\n                          ARRAY['ops', 'iam', 'portfolio', 'catalog', 'evidence', 'editorial', 'ai', 'policy']::text[]\n                      )\n                  AND (\n                      namespace_record.nspowner = login.login_oid\n                      OR pg_catalog.pg_has_role(\n                          login.login_oid, namespace_record.nspowner, 'MEMBER'\n                      )\n                  )\n           ) AS safe\n)\nSELECT login.login_role,\n       groups.inherited_groups,\n       login.is_superuser,\n       login.bypass_rls,\n       login.create_role,\n       login.create_database,\n       ownership.owns_selected_relation\n  FROM login_identity AS login\n  CROSS JOIN effective_groups AS groups\n  CROSS JOIN required_group_gate AS required_group\n  CROSS JOIN selected_inventory_gate AS inventory\n  CROSS JOIN selected_relation_ownership AS ownership\n  CROSS JOIN dangerous_owner_gate AS dangerous_owner\n WHERE required_group.usable\n   AND inventory.exact\n   AND dangerous_owner.safe"
IDENTITY_FACTS_SQL: Final[TextClause] = text(IDENTITY_FACTS_SQL_TEXT)

